  var I18N_ES = {};
  document.querySelectorAll('[data-i18n]').forEach(function(el){
    I18N_ES[el.dataset.i18n] = el.innerHTML;
  });
  var currentLang = localStorage.getItem('igc-lang') || 'es';

  function applyLang(lang){
    currentLang = lang;
    var dict = lang === 'en' ? I18N_EN : I18N_ES;
    document.querySelectorAll('[data-i18n]').forEach(function(el){
      var key = el.dataset.i18n;
      if (dict[key] !== undefined) el.innerHTML = dict[key];
    });
    document.documentElement.lang = lang;
    document.querySelectorAll('[data-lang-btn]').forEach(function(btn){
      btn.classList.toggle('active', btn.dataset.langBtn === lang);
    });
    var cvLink = document.getElementById('cv-download');
    if (cvLink) {
      if (lang === 'en') {
        cvLink.href = 'assets/cv/CV_Ignacio_Gonzalez_Cid_EN.pdf';
        cvLink.setAttribute('download', 'CV_Ignacio_Gonzalez_EN.pdf');
      } else {
        cvLink.href = 'assets/cv/CV_Ignacio_Gonzalez_Cid_ES.pdf';
        cvLink.setAttribute('download', 'CV_Ignacio_Gonzalez.pdf');
      }
    }
    try { localStorage.setItem('igc-lang', lang); } catch(e) {}
  }
  document.querySelectorAll('[data-lang-btn]').forEach(function(btn){
    btn.addEventListener('click', function(){
      if (btn.dataset.langBtn !== currentLang) applyLang(btn.dataset.langBtn);
    });
  });
  applyLang(currentLang);

  var menuToggle = document.getElementById('menu-toggle');
  var navRight = document.getElementById('nav-right');
  function closeMobileMenu(){
    if (!menuToggle || !navRight) return;
    navRight.classList.remove('mobile-open');
    menuToggle.classList.remove('is-open');
    menuToggle.setAttribute('aria-expanded', 'false');
  }
  if (menuToggle && navRight) {
    menuToggle.addEventListener('click', function(){
      var open = navRight.classList.toggle('mobile-open');
      menuToggle.classList.toggle('is-open', open);
      menuToggle.setAttribute('aria-expanded', open ? 'true' : 'false');
    });
    navRight.querySelectorAll('a, .lang-switch button').forEach(function(el){
      el.addEventListener('click', closeMobileMenu);
    });
    document.addEventListener('keydown', function(e){
      if (e.key === 'Escape') closeMobileMenu();
    });
  }

  function applyRoute(){
    var hash = location.hash.replace('#/','') || 'home';
    var pages = document.querySelectorAll('.page');
    for(var i=0;i<pages.length;i++){
      pages[i].hidden = pages[i].dataset.route !== hash;
    }
    var links = document.querySelectorAll('[data-route-link]');
    for(var j=0;j<links.length;j++){
      links[j].classList.toggle('active', links[j].dataset.routeLink === hash);
    }
    var active = document.querySelector('.page[data-route="'+hash+'"]');
    if(active){
      var heading = active.querySelector('h1,h2');
      if(heading){
        heading.setAttribute('tabindex','-1');
        heading.focus({preventScroll:true});
      }
    }
    window.scrollTo(0,0);
  }

  var lazyVideoObserver = 'IntersectionObserver' in window ? new IntersectionObserver(function(entries){
    entries.forEach(function(entry){
      var v = entry.target;
      if (entry.isIntersecting) {
        if (v.dataset.src) {
          v.autoplay = true;
          v.src = v.dataset.src;
          v.removeAttribute('data-src');
          v.load();
        }
        setTimeout(function(){ v.play().catch(function(){}); }, 30);
      } else if (!v.paused) {
        v.pause();
      }
    });
  }, { threshold: 0.25 }) : null;

  document.querySelectorAll('video[data-src]').forEach(function(v){
    if (lazyVideoObserver) {
      lazyVideoObserver.observe(v);
    } else {
      v.autoplay = true;
      v.src = v.dataset.src;
      v.removeAttribute('data-src');
      v.load();
      v.play().catch(function(){});
    }
  });

  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var pageTransition = document.querySelector('.page-transition');

  function navigate(){
    if(reduceMotion || !pageTransition){ applyRoute(); return; }
    pageTransition.classList.add('is-active');
    setTimeout(function(){
      applyRoute();
      setTimeout(function(){
        pageTransition.classList.remove('is-active');
      }, 160);
    }, 620);
  }
  window.addEventListener('hashchange', navigate);
  if (reduceMotion) {
    document.querySelectorAll('.video-tile video').forEach(function(v){
      v.removeAttribute('autoplay'); v.removeAttribute('loop'); v.pause(); v.setAttribute('controls','');
    });
  }
  applyRoute();

  var lightbox = document.createElement('div');

  var contactForm = document.getElementById('contact-form');
  if (contactForm) {
    contactForm.addEventListener('submit', function(e){
      e.preventDefault();
      var name = document.getElementById('cf-name').value;
      var email = document.getElementById('cf-email').value;
      var message = document.getElementById('cf-message').value;
      var isEn = currentLang === 'en';
      var subject = encodeURIComponent((isEn ? 'Portfolio contact — ' : 'Contacto desde el portfolio — ') + name);
      var body = encodeURIComponent((isEn ? 'Name: ' : 'Nombre: ') + name + '\nEmail: ' + email + '\n\n' + message);
      window.location.href = 'mailto:ngc3dmodeler@gmail.com,igcdsign@gmail.com?subject=' + subject + '&body=' + body;
    });
  }

  lightbox.className = 'lightbox-overlay';
  var lightboxImg = document.createElement('img');
  var lightboxVideo = document.createElement('video');
  lightboxVideo.muted = true;
  lightboxVideo.loop = true;
  lightboxVideo.playsInline = true;
  lightboxVideo.controls = true;
  lightbox.appendChild(lightboxImg);
  lightbox.appendChild(lightboxVideo);
  document.body.appendChild(lightbox);

  function closeLightbox(){
    lightbox.classList.remove('is-open');
    document.body.style.overflow = '';
    lightboxVideo.pause();
  }
  function openImage(src, alt){
    lightboxVideo.style.display = 'none';
    lightboxVideo.pause();
    lightboxImg.style.display = 'block';
    lightboxImg.src = src;
    lightboxImg.alt = alt || '';
    lightbox.classList.add('is-open');
    document.body.style.overflow = 'hidden';
  }
  function openVideo(src){
    lightboxImg.style.display = 'none';
    lightboxVideo.style.display = 'block';
    lightboxVideo.src = src;
    lightbox.classList.add('is-open');
    document.body.style.overflow = 'hidden';
    lightboxVideo.play().catch(function(){});
  }
  lightbox.addEventListener('click', function(e){
    if (e.target === lightboxVideo) return;
    closeLightbox();
  });
  document.addEventListener('keydown', function(e){
    if (e.key === 'Escape') closeLightbox();
  });
  document.querySelectorAll('.gallery img, .featured-media img, .detail-hero-media img').forEach(function(el){
    el.addEventListener('click', function(){ openImage(el.src, el.alt); });
  });
  document.querySelectorAll('.video-tile video').forEach(function(el){
    el.addEventListener('click', function(){ openVideo(el.currentSrc || el.src); });
  });
